param(
    [string]$Destination = (Join-Path (Get-Location) 'cdt-workflow-target-integration')
)

$ErrorActionPreference = 'Stop'
$expectedSha256 = '603B357196450F0B52B5A724D596D90BC7DE7363EF05C34B7BFF279ABECD2F69'
$base64 = @'

'@
$destinationPath = [IO.Path]::GetFullPath($Destination)
if (Test-Path -LiteralPath $destinationPath) {
    if (Get-ChildItem -LiteralPath $destinationPath -Force | Select-Object -First 1) {
        throw "Destination already exists and is not empty: $destinationPath"
    }
} else {
    New-Item -ItemType Directory -Path $destinationPath -Force | Out-Null
}

$temporaryZip = Join-Path ([IO.Path]::GetTempPath()) ("cdt-workflow-target-" + [Guid]::NewGuid().ToString('N') + '.zip')
try {
    [IO.File]::WriteAllBytes($temporaryZip, [Convert]::FromBase64String($base64))
    $actualSha256 = (Get-FileHash -LiteralPath $temporaryZip -Algorithm SHA256).Hash
    if ($actualSha256 -ne $expectedSha256) {
        throw "Bundle checksum mismatch. Expected $expectedSha256 but got $actualSha256."
    }
    Expand-Archive -LiteralPath $temporaryZip -DestinationPath $destinationPath -Force
    Write-Host "Restored target-integration bundle to: $destinationPath"
    Write-Host "Payload SHA256: $actualSha256"
} finally {
    if (Test-Path -LiteralPath $temporaryZip) {
        Remove-Item -LiteralPath $temporaryZip -Force
    }
}